/* Build-time adapter contract. Bundle this file with local sql.js and fflate; do not load them from a CDN. */
import initSqlJs from 'sql.js';import {zipSync,strToU8} from 'fflate';
const escHtml=(s:string)=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
export async function buildAnkiPackage({deck,cards,deckId,modelId}:any){const SQL=await initSqlJs({locateFile:(n:string)=>n.endsWith('.wasm')?'/assets/vendor/sqljs/sql-wasm.wasm':`./vendor/${n}`}),db=new SQL.Database(),now=Math.floor(Date.now()/1000),ms=Date.now();db.run(`CREATE TABLE col (id integer primary key, crt integer not null, mod integer not null, scm integer not null, ver integer not null, dty integer not null, usn integer not null, ls integer not null, conf text not null, models text not null, decks text not null, dconf text not null, tags text not null);CREATE TABLE notes (id integer primary key, guid text not null, mid integer not null, mod integer not null, usn integer not null, tags text not null, flds text not null, sfld integer not null, csum integer not null, flags integer not null, data text not null);CREATE TABLE cards (id integer primary key, nid integer not null, did integer not null, ord integer not null, mod integer not null, usn integer not null, type integer not null, queue integer not null, due integer not null, ivl integer not null, factor integer not null, reps integer not null, lapses integer not null, left integer not null, odue integer not null, odid integer not null, flags integer not null, data text not null);CREATE TABLE revlog (id integer primary key, cid integer not null, usn integer not null, ease integer not null, ivl integer not null, lastIvl integer not null, factor integer not null, time integer not null, type integer not null);CREATE TABLE graves (usn integer not null, oid integer not null, type integer not null);`);const model:any={id:modelId,name:'Basic',type:0,mod:now,usn:-1,sortf:0,did:deckId,tmpls:[{name:'Card 1',ord:0,qfmt:'{{Front}}',afmt:'{{FrontSide}}<hr id=answer>{{Back}}',did:null,bqfmt:'',bafmt:''}],flds:[{name:'Front',ord:0,sticky:false,rtl:false,font:'Arial',size:20,media:[]},{name:'Back',ord:1,sticky:false,rtl:false,font:'Arial',size:20,media:[]}],css:'.card { font-family: arial; font-size: 20px; text-align: center; color: black; background-color: white; }',latexPre:'',latexPost:'',latexsvg:false,req:[[0,'all',[0]]],tags:[],vers:[]};const deckObj:any={id:deckId,mod:now,name:deck,usn:-1,lrnToday:[0,0],revToday:[0,0],newToday:[0,0],timeToday:[0,0],collapsed:false,browserCollapsed:false,desc:'',dyn:0,extendNew:0,extendRev:0,conf:1};db.run('INSERT INTO col VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[1,now,now,ms,11,0,0,0,'{}',JSON.stringify({[modelId]:model}),JSON.stringify({[deckId]:deckObj}),'{}','{}']);const ns=db.prepare('INSERT INTO notes VALUES (?,?,?,?,?,?,?,?,?,?,?)'),cs=db.prepare('INSERT INTO cards VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');cards.forEach((c:any,i:number)=>{const nid=ms*1000+i,cid=nid+500000,guid=(nid>>>0).toString(36),front=escHtml(c.front),back=escHtml(c.back),flds=front+'\x1f'+back,tags=' '+c.tags.join(' ')+' ';let checksum=0;for(let j=0;j<front.length;j++)checksum=(Math.imul(checksum,31)+front.charCodeAt(j))>>>0;ns.run([nid,guid,modelId,now,-1,tags,flds,front,checksum,0,'']);cs.run([cid,nid,deckId,0,now,-1,0,0,i+1,0,0,0,0,0,0,0,0,''])});ns.free();cs.free();const dbBytes=db.export();db.close();return zipSync({'collection.anki2':dbBytes,'media':strToU8('{}')},{level:6})}
(window as any).buildAnkiPackage=buildAnkiPackage;
